create table if not exists public.job_vacancies(id uuid primary key default gen_random_uuid(),title text not null,department text not null default '',location text not null default 'Sri Ganganagar, Rajasthan',employment_type text not null default 'Full-time',salary text not null default '',eligibility text not null default '',description text not null,last_date date,is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.job_applications(id uuid primary key default gen_random_uuid(),job_id uuid not null references public.job_vacancies(id) on delete cascade,full_name text not null,email text not null,phone text not null,qualification text not null default '',message text not null default '',resume_link text not null default '',status text not null default 'New' check(status in('New','Shortlisted','Contacted','Rejected','Hired')),created_at timestamptz not null default now());
alter table public.job_vacancies enable row level security;alter table public.job_applications enable row level security;
drop policy if exists "Public can view active vacancies" on public.job_vacancies;create policy "Public can view active vacancies" on public.job_vacancies for select to anon,authenticated using(is_active=true);
drop policy if exists "Admins manage vacancies" on public.job_vacancies;create policy "Admins manage vacancies" on public.job_vacancies for all to authenticated using(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin')) with check(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin'));
drop policy if exists "Public can submit job applications" on public.job_applications;create policy "Public can submit job applications" on public.job_applications for insert to anon,authenticated with check(exists(select 1 from public.job_vacancies j where j.id=job_id and j.is_active=true and (j.last_date is null or j.last_date>=current_date)) and length(trim(full_name)) between 2 and 120 and length(trim(email)) between 5 and 254 and length(trim(phone)) between 8 and 20);
drop policy if exists "Admins manage job applications" on public.job_applications;create policy "Admins manage job applications" on public.job_applications for all to authenticated using(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin')) with check(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin'));
-- City-wise vacancy browsing support
alter table public.job_vacancies add column if not exists city text not null default 'Sri Ganganagar';
update public.job_vacancies set city=coalesce(nullif(split_part(location,',',1),''),'Sri Ganganagar') where city is null or city='';
